var own=['settings','settings--sign-out'];doc.pages.filter(p=>['Proto iOS Light','Proto iOS Dark'].includes(p.name)).forEach(p=>p.layers.filter(s=>s.name.startsWith('Screen/ios/')&&own.includes(s.name.split('/').pop())).forEach(s=>{var top=s.layers.find(l=>l.name==='top'),nav=top.layers.find(l=>l.name==='nav-bar'),large=nav.layers.find(l=>l.name==='large-title');if(large)large.remove();var bar=nav.layers.find(l=>l.name==='bar');var title=bar.layers.find(l=>l.type==='Text');title.text='Settings';bar.stackLayout.apply();nav.stackLayout.apply();top.stackLayout.apply();var b=s.layers.find(l=>l.name==='body');b.stackLayout.gap=4;b.stackLayout.padding={top:0,right:16,bottom:0,left:16};var prof=b.layers.find(l=>l.name==='link:settings-account');prof.frame.height=44;prof.stackLayout.padding={top:0,right:12,bottom:0,left:12};var av=prof.layers.find(l=>l.name==='avatar');av.frame.width=36;av.frame.height=36;av.stackLayout.apply();prof.stackLayout.apply();b.layers.filter(l=>l!==prof).forEach(g=>{var rows=g.layers.find(l=>l.name==='rows');if(rows){rows.layers.filter(l=>l.name!=='sep'&&!l.name.startsWith('sep ')).forEach(row=>{row.frame.height=44;row.stackLayout.apply();});rows.stackLayout.apply();g.stackLayout.apply();}});b.stackLayout.apply();if(s.stackLayout)s.stackLayout.apply();else{b.frame.y=98;b.frame.height=650;}console.log(JSON.stringify({id:String(s.id),name:s.name,last:Math.max.apply(null,b.layers.map(l=>l.frame.y+l.frame.height))+b.frame.y}));}));